    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    import numpy as np

    df['Wk_End_Dt'] = pd.to_datetime(df['Wk_End_Dt'])

    sale_return_rows = df[df['row_kind'].isin(['sale', 'return'])].copy()

    max_date = sale_return_rows['Wk_End_Dt'].max()
    period2_end = max_date
    period2_start = period2_end - pd.Timedelta(weeks=52) + pd.Timedelta(days=1)
    period1_end = period2_start - pd.Timedelta(days=1)
    period1_start = period1_end - pd.Timedelta(weeks=52) + pd.Timedelta(days=1)

    p1 = sale_return_rows[(sale_return_rows['Wk_End_Dt'] >= period1_start) & (sale_return_rows['Wk_End_Dt'] <= period1_end)].copy()
    p2 = sale_return_rows[(sale_return_rows['Wk_End_Dt'] >= period2_start) & (sale_return_rows['Wk_End_Dt'] <= period2_end)].copy()

    p1_stores_by_region = p1.groupby('Region')['Store_No'].apply(set)
    p2_stores_by_region = p2.groupby('Region')['Store_No'].apply(set)

    all_regions = set(p1_stores_by_region.index) | set(p2_stores_by_region.index)

    comp_results = []
    total_results = []

    for region in sorted(all_regions):
        s1 = p1_stores_by_region.get(region, set())
        s2 = p2_stores_by_region.get(region, set())
        comp_stores = s1 & s2

        p1_region = p1[p1['Region'] == region]
        p2_region = p2[p2['Region'] == region]

        p1_comp = p1_region[p1_region['Store_No'].isin(comp_stores)]['Net Sales'].sum()
        p2_comp = p2_region[p2_region['Store_No'].isin(comp_stores)]['Net Sales'].sum()

        if p1_comp != 0:
            comp_growth = (p2_comp - p1_comp) / abs(p1_comp)
        else:
            comp_growth = float('nan')

        comp_results.append({"name": region, "value": round(comp_growth, 6)})

        p1_total = p1_region['Net Sales'].sum()
        p2_total = p2_region['Net Sales'].sum()
        if p1_total != 0:
            total_growth = (p2_total - p1_total) / abs(p1_total)
        else:
            total_growth = float('nan')

        total_results.append({"name": region, "value": round(total_growth, 6)})

    all_comp_stores_p1 = set(p1['Store_No'].unique()) & set(p2['Store_No'].unique())
    p1_overall_comp = p1[p1['Store_No'].isin(all_comp_stores_p1)]['Net Sales'].sum()
    p2_overall_comp = p2[p2['Store_No'].isin(all_comp_stores_p1)]['Net Sales'].sum()
    if p1_overall_comp != 0:
        overall_comp_growth = (p2_overall_comp - p1_overall_comp) / abs(p1_overall_comp)
