    import numpy as np

    df['Wk_End_Dt'] = pd.to_datetime(df['Wk_End_Dt'])

    sale_rows = df[df['row_kind'].isin(['sale', 'return'])].copy()

    max_date = sale_rows['Wk_End_Dt'].max()
    period_end = max_date
    period1_start = period_end - pd.Timedelta(weeks=52) + pd.Timedelta(days=1)
    period0_end = period1_start - pd.Timedelta(days=1)
    period0_start = period0_end - pd.Timedelta(weeks=52) + pd.Timedelta(days=1)

    curr = sale_rows[(sale_rows['Wk_End_Dt'] >= period1_start) & (sale_rows['Wk_End_Dt'] <= period_end)]
    prev = sale_rows[(sale_rows['Wk_End_Dt'] >= period0_start) & (sale_rows['Wk_End_Dt'] <= period0_end)]

    curr_stores = set(curr['Store_No'].unique())
    prev_stores = set(prev['Store_No'].unique())
    comp_stores = curr_stores & prev_stores

    curr_comp = curr[curr['Store_No'].isin(comp_stores)]
    prev_comp = prev[prev['Store_No'].isin(comp_stores)]

    regions = sorted(sale_rows['Region'].dropna().unique())

    comp_results = []
    for region in regions:
        curr_r = curr_comp[curr_comp['Region'] == region]['Net Sales'].sum()
        prev_r = prev_comp[prev_comp['Region'] == region]['Net Sales'].sum()
        if prev_r != 0:
            growth = (curr_r - prev_r) / abs(prev_r)
        else:
            growth = float('nan')
        comp_results.append({"name": str(region), "value": round(growth, 6)})

    curr_total = curr_comp['Net Sales'].sum()
    prev_total = prev_comp['Net Sales'].sum()
    overall_growth = (curr_total - prev_total) / abs(prev_total) if prev_total != 0 else float('nan')
    comp_results.append({"name": "Overall (comp)", "value": round(overall_growth, 6)})

    result['segments'].append({
        "segment_column": "Region",
        "metric_column": "Net Sales",
        "aggregation": "ratio",
        "label": "comp_sales_growth_52w",
        "results": comp_results
    })

    curr_abs = []
    prev_abs = []
    for region in regions:
        curr_r = curr_comp[curr_comp['Region'] == region]['Net Sales'].sum()
        prev_r = prev_comp[prev_comp['Region'] == region]['Net Sales'].sum()
        curr_abs.append({"name": str(region), "value": round(curr_r, 2)})
        prev_abs.append({"name": str(region), "value": round(prev_r, 2)})

    result['segments'].append({
        "segment_column": "Region",
        "metric_column": "Net Sales",
        "aggregation": "sum",
        "label": "comp_net_sales_current_52w",
        "results": curr_abs
    })

    result['segments'].append({
        "segment_column": "Region",
        "metric_column": "Net Sales",
        "aggregation": "sum",
        "label": "comp_net_sales_prior_52w",
        "results": prev_abs
    })

    n_comp = len(comp_stores)
    n_curr_only = len(curr_stores - prev_stores)
    n_prev_only = len(prev_stores - curr_stores)

    result['assumptions'].append(
        f"Comp stores: {n_comp} stores present in both 52-week periods; "
        f"{n_curr_only} new-period-only and {n_prev_only} prior-period-only stores excluded from comp growth."
    )
    result['assumptions'].append(
        f"Current period: {period1_start.date()} to {period_end.date()}; "
        f"Prior period: {period0_start.date()} to {period0_end.date()}."
    )
    result['assumptions'].append(
        "Net Sales computed over sale and return rows only (row_kind in ['sale','return'])."
    )
    result['assumptions'].append(
        "Comp growth = (current_net_sales - prior_net_sales) / abs(prior_net_sales), expressed as a fraction."
    )

except Exception as e:
