    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    sale_return_mask = df['row_kind'].isin(['sale', 'return'])
    sale_mask = df['row_kind'] == 'sale'

    df_net = df[sale_return_mask].copy()
    df_net['net_sales_line'] = df_net['Quantity'] * df_net['UnitPrice']

    df_sales = df[sale_mask].copy()
    df_sales['sales_line'] = df_sales['Quantity'] * df_sales['UnitPrice']

    top5_by_sales = (
        df_sales.groupby('StockCode')['sales_line']
        .sum()
        .nlargest(5)
        .index.tolist()
    )

    net_by_sku = (
        df_net[df_net['StockCode'].isin(top5_by_sales)]
        .groupby('StockCode')['net_sales_line']
        .sum()
    )

    net_results = [
        {"name": str(sku), "value": round(float(net_by_sku.get(sku, 0.0)), 2)}
        for sku in top5_by_sales
    ]

    result['segments'].append({
        "segment_column": "StockCode",
        "metric_column": "Quantity",
        "aggregation": "ratio",
        "label": "net_sales",
        "results": net_results
    })

    result['assumptions'].append(
        "Top 5 products ranked by gross sales value (sale rows only); net sales include returns."
    )
    result['assumptions'].append(
        "net_sales = sum(Quantity × UnitPrice) over sale and return rows for each StockCode."
    )
except Exception as e:
    result['segments'].append({
        "segment_column": "StockCode",
        "metric_column": "Quantity",
        "aggregation": "ratio",
        "label": "net_sales",
        "results": [{"name": "error", "value": 0.0}]
    })
    result['assumptions'].append(f"Segmentation error: {str(e)}")

# ─── Standard statistics (deterministic) ───
result['builtin'] = []
_targets, _segs, _date, _hints = ['Quantity', 'UnitPrice'], ['StockCode'], 'InvoiceDate', {}
try:
    if False:
        for _i, _a in enumerate(_targets):
            for _b in _targets[_i + 1:]:
                if f'{_a}__{_b}' not in result['correlations'] and f'{_b}__{_a}' not in result['correlations']:
                    _r = df[_a].corr(df[_b])
                    if _r == _r:
